/*
 * A cohesive, luxurious dark theme using shades of brown and beige.
 * This version is simplified for maximum compatibility with Stylish.
 */

/* =======================================
   1. The Core Palette & Universal Styles
   ======================================= */

/* Set the main background color for the entire page */
html, body {
  background-color: #3A2E2A !important;
}

/* Set universal text and link colors */
* {
  color: #F5F0E6 !important;
  font-family: serif !important;
}

/* Ensure common text and container elements have the right background */
p, span, li, a, h1, h2, h3, h4, h5, h6,
div, main, section, article, header, footer {
    background-color: transparent !important;
}

/* =======================================
   2. Interactive Elements: Buttons & Forms
   ======================================= */

button, input[type="submit"], input[type="button"] {
  background-color: #6B5A4A !important;
  color: #F5F0E6 !important;
  border: 1px solid #6B5A4A !important;
  padding: 12px 24px !important;
  border-radius: 5px !important;
  font-weight: bold !important;
  cursor: pointer !important;
}

button:hover, input[type="submit"]:hover, input[type="button"]:hover {
  background-color: #4D3E30 !important;
  border-color: #4D3E30 !important;
}

a {
  color: #D4C4B5 !important;
  text-decoration: none !important;
  transition: all 0.2s ease-in-out !important;
}

a:hover {
  color: #F5F0E6 !important;
  border-bottom: 1px solid #F5F0E6 !important;
}

input[type="text"],
input[type="email"],
input[type="password"],
textarea {
  background-color: #4D3E30 !important;
  border: 1px solid #6B5A4A !important;
  border-radius: 4px !important;
  color: #F5F0E6 !important;
  padding: 10px !important;
}

input:focus, textarea:focus {
  border-color: #D4C4B5 !important;
  outline: none !important;
}
